/**
 * sitemap.xml (generated by Next.js Metadata API)
 * ===============================================
 * Serves /sitemap.xml with the homepage and every project detail page. A clean
 * sitemap helps search and AI crawlers discover and re-crawl all indexable URLs.
 */

import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site";
import { getAllProjects } from "@/lib/projects";

export default function sitemap(): MetadataRoute.Sitemap {
  const lastModified = new Date();

  const projectRoutes: MetadataRoute.Sitemap = getAllProjects().map(
    (project) => ({
      url: `${SITE_URL}/projects/${project.slug}`,
      lastModified,
      changeFrequency: "monthly",
      priority: 0.8,
    })
  );

  const staticRoutes: MetadataRoute.Sitemap = [
    "/about",
    "/services",
    "/projects",
  ].map((path) => ({
    url: `${SITE_URL}${path}`,
    lastModified,
    changeFrequency: "monthly",
    priority: 0.8,
  }));

  return [
    {
      url: SITE_URL,
      lastModified,
      changeFrequency: "monthly",
      priority: 1,
    },
    ...staticRoutes,
    ...projectRoutes,
  ];
}
